class UserAuthRoutes:
    """用户认证API路由"""
    
    def __init__(self, user_auth_manager: UserAuthManager, template_manager: UserTemplateManager):
        """
        初始化用户认证路由
        
        Args:
            user_auth_manager: 用户认证管理器
            template_manager: 模板管理器
        """
        self.user_auth_manager = user_auth_manager
        self.template_manager = template_manager
    
    def _get_client_ip(self, request: web.Request) -> str:
        """获取客户端IP地址"""
        # 尝试从X-Forwarded-For头部获取真实IP
        forwarded_for = request.headers.get('X-Forwarded-For')
        if forwarded_for:
            # 取第一个IP（客户端真实IP）
            return forwarded_for.split(',')[0].strip()
        
        # 尝试从X-Real-IP头部获取
        real_ip = request.headers.get('X-Real-IP')
        if real_ip:
            return real_ip
        
        # 使用连接远程地址
        return request.remote
    
    async def _rate_limit_middleware(self, request: web.Request, handler: Callable, 
                                     rate_limit_type: str = "api", user_id: str = None) -> web.Response:
        """
        速率限制中间件
        
        Args:
            request: 请求对象
            handler: 处理函数
            rate_limit_type: 速率限制类型（"login", "register", "api"）
            user_id: 用户ID（可选）
            
        Returns:
            web.Response: 响应对象
        """
        client_ip = self._get_client_ip(request)
        
        # 检查IP白名单
        if not security_manager.is_ip_allowed(client_ip):
            return web.json_response({
                "success": False,
                "message": "IP地址不在白名单中"
            }, status=403)
        
        # 检查IP黑名单
        if security_manager.is_ip_blocked(client_ip):
            return web.json_response({
                "success": False,
                "message": "IP地址已被阻止"
            }, status=403)
        
        # 检查速率限制
        if rate_limit_type == "login":
            allowed, remaining, reset_in = security_manager.check_login_rate_limit(client_ip)
        elif rate_limit_type == "register":
            allowed, remaining, reset_in = security_manager.check_register_rate_limit(client_ip)
        else:  # "api" or default
            allowed, remaining, reset_in = security_manager.check_api_rate_limit(user_id, client_ip)
        
        if not allowed:
            return web.json_response({
                "success": False,
                "message": "请求过于频繁，请稍后再试",
                "data": {
                    "remaining": 0,
                    "reset_in": reset_in
                }
            }, status=429)
        
        # 添加速率限制头部
        response = await handler(request)
        response.headers['X-RateLimit-Limit'] = str(100 if rate_limit_type == "api" else (10 if rate_limit_type == "login" else 5))
        response.headers['X-RateLimit-Remaining'] = str(remaining)
        response.headers['X-RateLimit-Reset'] = str(reset_in)
        
        return response
    
    async def _auth_middleware(self, request: web.Request, handler: Callable) -> web.Response:
        """
        认证中间件
        
        Args:
            request: 请求对象
            handler: 处理函数
            
        Returns:
            web.Response: 响应对象
        """
        # 获取客户端IP
        client_ip = self._get_client_ip(request)
        
        # 检查IP白名单
        if not security_manager.is_ip_allowed(client_ip):
            return web.json_response({
                "success": False,
                "message": "IP地址不在白名单中"
            }, status=403)
        
        # 检查IP黑名单
        if security_manager.is_ip_blocked(client_ip):
            return web.json_response({
                "success": False,
                "message": "IP地址已被阻止"
            }, status=403)
        
        # 获取会话令牌
        auth_header = request.headers.get("Authorization")
        if not auth_header or not auth_header.startswith("Bearer "):
            return web.json_response({
                "success": False,
                "message": "缺少认证令牌"
            }, status=401)
        
        session_token = auth_header[7:]  # 移除 "Bearer " 前缀
        
        # 验证会话并获取用户
        success, message, user = self.user_auth_manager.verify_session(session_token)
        
        if not success:
            return web.json_response({
                "success": False,
                "message": message
            }, status=401)
        
        # 检查API速率限制
        allowed, remaining, reset_in = security_manager.check_api_rate_limit(user["id"], client_ip)
        
        if not allowed:
            return web.json_response({
                "success": False,
                "message": "请求过于频繁，请稍后再试",
                "data": {
                    "remaining": 0,
                    "reset_in": reset_in
                }
            }, status=429)
        
        # 将用户信息添加到请求中
        request["user"] = user
        
        # 调用处理函数
        response = await handler(request)
        
        # 添加速率限制头部
        response.headers['X-RateLimit-Limit'] = '100'
        response.headers['X-RateLimit-Remaining'] = str(remaining)
        response.headers['X-RateLimit-Reset'] = str(reset_in)
        
        return response
    
    def add_routes(self, routes):
        """添加路由到应用"""
        
        @routes.post("/api/auth/register")
        async def register_user(request):
            """
            用户注册
            
            Request Body:
            {
                "username": "用户名",
                "password": "密码",
                "email": "邮箱（可选）",
                "display_name": "显示名称（可选）"
            }
            
            Response:
            {
                "success": true,
                "message": "注册成功",
                "data": {
                    "user_id": "用户ID",
                    "username": "用户名",
                    "display_name": "显示名称",
                    "email": "邮箱"
                }
            }
            """
            # 应用速率限制中间件
            return await self._rate_limit_middleware(
                request, 
                self._register_user_handler, 
                rate_limit_type="register"
            )
        
        async def _register_user_handler(self, request):
            """注册用户处理函数"""
            try:
                data = await request.json()
            except json.JSONDecodeError:
                return web.json_response({
                    "success": False,
                    "message": "无效的JSON数据"
                }, status=400)
            
            # 验证必需字段
            required_fields = ["username", "password"]
            for field in required_fields:
                if field not in data:
                    return web.json_response({
                        "success": False,
                        "message": f"缺少必需字段: {field}"
                    }, status=400)
            
            username = data.get("username", "").strip()
            password = data.get("password", "")
            email = data.get("email", "").strip() or None
            display_name = data.get("display_name", "").strip() or None
            
            # 注册用户
            success, message, user = self.user_auth_manager.register_user(
                username=username,
                password=password,
                email=email,
                display_name=display_name
            )
            
            if not success:
                return web.json_response({
                    "success": False,
                    "message": message
                }, status=400)
            
            return web.json_response({
                "success": True,
                "message": message,
                "data": {
                    "user_id": user.id,
                    "username": user.username,
                    "display_name": user.display_name,
                    "email": user.email,
                    "created_at": user.created_at.isoformat()
                }
            })
        
        @routes.post("/api/auth/login")
        async def login_user(request):
            """
            用户登录
            
            Request Body:
            {
                "username": "用户名",
                "password": "密码"
            }
            
            Response:
            {
                "success": true,
                "message": "登录成功",
                "data": {
                    "user_id": "用户ID",
                    "username": "用户名",
                    "display_name": "显示名称",
                    "email": "邮箱",
                    "is_admin": false,
                    "session_token": "会话令牌",
                    "refresh_token": "刷新令牌",
                    "expires_at": "会话过期时间",
                    "refresh_expires_at": "刷新令牌过期时间"
                }
            }
            """
            # 应用速率限制中间件
            return await self._rate_limit_middleware(
                request, 
                self._login_user_handler, 
                rate_limit_type="login"
            )
        
        async def _login_user_handler(self, request):
            """登录用户处理函数"""
            try:
                data = await request.json()
            except json.JSONDecodeError:
                return web.json_response({
                    "success": False,
                    "message": "无效的JSON数据"
                }, status=400)
            
            # 验证必需字段
            required_fields = ["username", "password"]
            for field in required_fields:
                if field not in data:
                    return web.json_response({
                        "success": False,
                        "message": f"缺少必需字段: {field}"
                    }, status=400)
            
            username = data.get("username", "").strip()
            password = data.get("password", "")
            
            # 获取用户代理和IP地址
            user_agent = request.headers.get("User-Agent")
            ip_address = self._get_client_ip(request)
            
            # 用户登录
            success, message, session_info = self.user_auth_manager.login_user(
                username=username,
                password=password,
                user_agent=user_agent,
                ip_address=ip_address
            )
            
            if not success:
                return web.json_response({
                    "success": False,
                    "message": message
                }, status=401)
            
            return web.json_response({
                "success": True,
                "message": message,
                "data": session_info
            })
        
