        @routes.post("/api/auth/refresh")
        async def refresh_session(request):
            """
            刷新会话令牌
            
            Request Body:
            {
                "refresh_token": "刷新令牌"
            }
            
            Response:
            {
                "success": true,
                "message": "会话刷新成功",
                "data": {
                    "session_token": "新会话令牌",
                    "refresh_token": "新刷新令牌",
                    "expires_at": "新会话过期时间",
                    "refresh_expires_at": "新刷新令牌过期时间"
                }
            }
            """
            try:
                data = await request.json()
            except json.JSONDecodeError:
                return web.json_response({
                    "success": False,
                    "message": "无效的JSON数据"
                }, status=400)
            
            if "refresh_token" not in data:
                return web.json_response({
                    "success": False,
                    "message": "缺少刷新令牌"
                }, status=400)
            
            refresh_token = data["refresh_token"]
            
            # 获取用户代理和IP地址
            user_agent = request.headers.get("User-Agent")
            ip_address = request.remote
            
            # 刷新会话
            success, message, session_info = self.user_auth_manager.refresh_session(
                refresh_token=refresh_token,
                user_agent=user_agent,
                ip_address=ip_address
            )
            
            if not success:
                return web.json_response({
                    "success": False,
                    "message": message
                }, status=401)
            
            return web.json_response({
                "success": True,
                "message": message,
                "data": session_info
            })
        
