        @routes.post("/api/auth/change-password")
        async def change_password(request):
            """
            修改密码
            
            Headers:
            Authorization: Bearer {session_token}
            
            Request Body:
            {
                "old_password": "旧密码",
                "new_password": "新密码"
            }
            
            Response:
            {
                "success": true,
                "message": "密码修改成功"
            }
            """
            # 获取会话令牌
            auth_header = request.headers.get("Authorization")
            if not auth_header or not auth_header.startswith("Bearer "):
                return web.json_response({
                    "success": False,
                    "message": "缺少认证令牌"
                }, status=401)
            
            session_token = auth_header[7:]  # 移除 "Bearer " 前缀
            
            # 验证会话并获取用户
            success, message, user = self.user_auth_manager.verify_session(session_token)
            
            if not success:
                return web.json_response({
                    "success": False,
                    "message": message
                }, status=401)
            
            try:
                data = await request.json()
            except json.JSONDecodeError:
                return web.json_response({
                    "success": False,
                    "message": "无效的JSON数据"
                }, status=400)
            
            # 验证必需字段
            required_fields = ["old_password", "new_password"]
            for field in required_fields:
                if field not in data:
                    return web.json_response({
                        "success": False,
                        "message": f"缺少必需字段: {field}"
                    }, status=400)
            
            old_password = data["old_password"]
            new_password = data["new_password"]
            
            # 修改密码
            success, message = self.user_auth_manager.change_password(
                user_id=user.id,
                old_password=old_password,
                new_password=new_password
            )
            
            if not success:
                return web.json_response({
                    "success": False,
                    "message": message
                }, status=400)
            
            return web.json_response({
                "success": True,
                "message": message
            })
        
