        # 模板管理API
        @routes.post("/api/templates")
        async def create_template(request):
            """
            创建模板
            
            Headers:
            Authorization: Bearer {session_token}
            
            Request Body:
            {
                "name": "模板名称",
                "workflow_data": "工作流数据（JSON字符串）",
                "description": "模板描述（可选）",
                "category": "分类（可选）",
                "tags": "标签，逗号分隔（可选）",
                "thumbnail": "缩略图base64（可选）",
                "is_public": false
            }
            
            Response:
            {
                "success": true,
                "message": "模板创建成功",
                "data": {
                    "template_id": "模板ID",
                    "name": "模板名称",
                    "description": "模板描述",
                    "category": "分类",
                    "tags": "标签",
                    "is_public": false,
                    "is_favorite": false,
                    "created_at": "创建时间"
                }
            }
            """
            # 获取会话令牌
            auth_header = request.headers.get("Authorization")
            if not auth_header or not auth_header.startswith("Bearer "):
                return web.json_response({
                    "success": False,
                    "message": "缺少认证令牌"
                }, status=401)
            
            session_token = auth_header[7:]  # 移除 "Bearer " 前缀
            
            # 验证会话并获取用户
            success, message, user = self.user_auth_manager.verify_session(session_token)
            
            if not success:
                return web.json_response({
                    "success": False,
                    "message": message
                }, status=401)
            
            try:
                data = await request.json()
            except json.JSONDecodeError:
                return web.json_response({
                    "success": False,
                    "message": "无效的JSON数据"
                }, status=400)
            
            # 验证必需字段
            required_fields = ["name", "workflow_data"]
            for field in required_fields:
                if field not in data:
                    return web.json_response({
                        "success": False,
                        "message": f"缺少必需字段: {field}"
                    }, status=400)
            
            # 创建模板
            success, message, template = self.template_manager.create_template(
                user_id=user.id,
                name=data["name"],
                workflow_data=data["workflow_data"],
                description=data.get("description"),
                category=data.get("category"),
                tags=data.get("tags"),
                thumbnail=data.get("thumbnail"),
                is_public=data.get("is_public", False)
            )
            
            if not success:
                return web.json_response({
                    "success": False,
                    "message": message
                }, status=400)
            
            return web.json_response({
                "success": True,
                "message": message,
                "data": {
                    "template_id": template.id,
                    "name": template.name,
                    "description": template.description,
                    "category": template.category,
                    "tags": template.tags,
                    "is_public": template.is_public,
                    "is_favorite": template.is_favorite,
                    "created_at": template.created_at.isoformat(),
                    "updated_at": template.updated_at.isoformat()
                }
            }, status=201)
        
        @routes.get("/api/templates")
        async def list_templates(request):
            """
            获取模板列表
            
            Headers:
            Authorization: Bearer {session_token}（可选，用于获取用户私有模板）
            
            Query Parameters:
            - include_public: 是否包含公开模板（默认false）
            - category: 按分类筛选
            - search: 搜索关键词
            - favorite_only: 是否只显示收藏的模板（默认false）
            - page: 页码（默认1）
            - page_size: 每页数量（默认20）
            - sort_by: 排序字段（name, created_at, updated_at, view_count, use_count，默认updated_at）
            - sort_order: 排序顺序（asc, desc，默认desc）
            
            Response:
            {
                "success": true,
                "data": {
                    "templates": [
                        {
                            "template_id": "模板ID",
                            "name": "模板名称",
                            "description": "模板描述",
                            "category": "分类",
                            "tags": "标签",
                            "is_public": false,
                            "is_favorite": false,
                            "view_count": 0,
                            "use_count": 0,
                            "created_at": "创建时间",
                            "updated_at": "更新时间",
                            "user_id": "用户ID",
                            "username": "用户名"
                        }
                    ],
                    "total": 100,
                    "page": 1,
                    "page_size": 20,
                    "total_pages": 5
                }
            }
            """
            # 尝试获取用户ID（如果提供了认证令牌）
            user_id = None
            auth_header = request.headers.get("Authorization")
            if auth_header and auth_header.startswith("Bearer "):
                session_token = auth_header[7:]
                success, message, user = self.user_auth_manager.verify_session(session_token)
                if success:
                    user_id = user.id
            
            # 获取查询参数
            query = request.rel_url.query
            include_public = query.get("include_public", "false").lower() == "true"
            category = query.get("category")
            search = query.get("search")
            favorite_only = query.get("favorite_only", "false").lower() == "true"
            
            try:
                page = int(query.get("page", "1"))
                page_size = int(query.get("page_size", "20"))
            except ValueError:
                return web.json_response({
                    "success": False,
                    "message": "页码和每页数量必须是整数"
                }, status=400)
            
            sort_by = query.get("sort_by", "updated_at")
            sort_order = query.get("sort_order", "desc")
            
            # 获取模板列表
            templates, total_count = self.template_manager.get_user_templates(
                user_id=user_id if user_id else "anonymous",
                include_public=include_public,
                category=category,
                search=search,
                favorite_only=favorite_only,
                page=page,
                page_size=page_size,
                sort_by=sort_by,
                sort_order=sort_order
            )
            
            # 计算总页数
            total_pages = (total_count + page_size - 1) // page_size if page_size > 0 else 0
            
            # 准备响应数据
            templates_data = []
            for template in templates:
                # 获取用户信息
                user = self.user_auth_manager.get_user_by_id(template.user_id)
                
                templates_data.append({
                    "template_id": template.id,
                    "name": template.name,
                    "description": template.description,
                    "category": template.category,
                    "tags": template.tags,
                    "is_public": template.is_public,
                    "is_favorite": template.is_favorite,
                    "view_count": template.view_count,
                    "use_count": template.use_count,
                    "created_at": template.created_at.isoformat(),
                    "updated_at": template.updated_at.isoformat(),
                    "user_id": template.user_id,
                    "username": user.username if user else "未知用户",
                    "display_name": user.display_name if user else "未知用户"
                })
            
            return web.json_response({
                "success": True,
                "data": {
                    "templates": templates_data,
                    "total": total_count,
                    "page": page,
                    "page_size": page_size,
                    "total_pages": total_pages
                }
            })
        
