        @routes.get("/api/admin/users")
        async def list_users(request):
            """
            获取用户列表（管理员功能）
            
            Headers:
            Authorization: Bearer {session_token}
            
            Query Parameters:
            page: 页码（默认1）
            page_size: 每页数量（默认20）
            search: 搜索关键词（用户名、邮箱、显示名称）
            is_active: 是否激活（true/false）
            is_admin: 是否管理员（true/false）
            
            Response:
            {
                "success": true,
                "data": {
                    "users": [
                        {
                            "id": "用户ID",
                            "username": "用户名",
                            "email": "邮箱",
                            "display_name": "显示名称",
                            "is_admin": false,
                            "is_active": true,
                            "created_at": "创建时间",
                            "updated_at": "更新时间",
                            "last_login_at": "最后登录时间"
                        }
                    ],
                    "total_count": 100,
                    "page": 1,
                    "page_size": 20
                }
            }
            """
            # 获取会话令牌
            auth_header = request.headers.get("Authorization")
            if not auth_header or not auth_header.startswith("Bearer "):
                return web.json_response({
                    "success": False,
                    "message": "缺少认证令牌"
                }, status=401)
            
            session_token = auth_header[7:]  # 移除 "Bearer " 前缀
            
            # 验证会话并获取用户
            success, message, user = self.user_auth_manager.verify_session(session_token)
            
            if not success:
                return web.json_response({
                    "success": False,
                    "message": message
                }, status=401)
            
            # 检查是否为管理员
            if not user.get("is_admin"):
                return web.json_response({
                    "success": False,
                    "message": "需要管理员权限"
                }, status=403)
            
            # 获取查询参数
            query = request.rel_url.query
            page = int(query.get("page", 1))
            page_size = min(int(query.get("page_size", 20)), 100)  # 限制最大100条
            search = query.get("search")
            is_active = query.get("is_active")
            is_admin = query.get("is_admin")
            
            # 转换布尔参数
            is_active_bool = None
            if is_active is not None:
                is_active_bool = is_active.lower() == "true"
            
            is_admin_bool = None
            if is_admin is not None:
                is_admin_bool = is_admin.lower() == "true"
            
            # 获取用户列表
            users, total_count = self.user_auth_manager.list_users(
                page=page,
                page_size=page_size,
                search=search,
                is_active=is_active_bool,
                is_admin=is_admin_bool
            )
            
            return web.json_response({
                "success": True,
                "data": {
                    "users": users,
                    "total_count": total_count,
                    "page": page,
                    "page_size": page_size
                }
            })
        
