        @routes.put("/api/admin/users/{user_id}")
        async def update_user(request):
            """
            更新用户信息（管理员功能）
            
            Headers:
            Authorization: Bearer {session_token}
            
            Path Parameters:
            user_id: 用户ID
            
            Request Body:
            {
                "username": "新用户名（可选）",
                "email": "新邮箱（可选）",
                "display_name": "新显示名称（可选）",
                "is_active": true/false（可选）,
                "is_admin": true/false（可选）
            }
            
            Response:
            {
                "success": true,
                "message": "用户信息更新成功",
                "data": {
                    "id": "用户ID",
                    "username": "用户名",
                    "email": "邮箱",
                    "display_name": "显示名称",
                    "is_admin": false,
                    "is_active": true,
                    "created_at": "创建时间",
                    "updated_at": "更新时间",
                    "last_login_at": "最后登录时间"
                }
            }
            """
            # 获取会话令牌
            auth_header = request.headers.get("Authorization")
            if not auth_header or not auth_header.startswith("Bearer "):
                return web.json_response({
                    "success": False,
                    "message": "缺少认证令牌"
                }, status=401)
            
            session_token = auth_header[7:]  # 移除 "Bearer " 前缀
            
            # 验证会话并获取用户
            success, message, current_user = self.user_auth_manager.verify_session(session_token)
            
            if not success:
                return web.json_response({
                    "success": False,
                    "message": message
                }, status=401)
            
            # 检查是否为管理员
            if not current_user.get("is_admin"):
                return web.json_response({
                    "success": False,
                    "message": "需要管理员权限"
                }, status=403)
            
            # 获取用户ID
            user_id = request.match_info.get("user_id")
            if not user_id:
                return web.json_response({
                    "success": False,
                    "message": "缺少用户ID"
                }, status=400)
            
            # 获取请求数据
            try:
                data = await request.json()
            except json.JSONDecodeError:
                return web.json_response({
                    "success": False,
                    "message": "无效的JSON数据"
                }, status=400)
            
            # 验证请求数据
            allowed_fields = ["username", "email", "display_name", "is_active", "is_admin"]
            update_data = {}
            
            for field in allowed_fields:
                if field in data:
                    update_data[field] = data[field]
            
            if not update_data:
                return web.json_response({
                    "success": False,
                    "message": "没有需要更新的字段"
                }, status=400)
            
            # 更新用户信息
            success, message, updated_user = self.user_auth_manager.update_user(user_id, **update_data)
            
            if not success:
                return web.json_response({
                    "success": False,
                    "message": message
                }, status=400)
            
            return web.json_response({
                "success": True,
                "message": message,
                "data": updated_user
            })
        
