        @routes.post("/api/admin/security/blacklist")
        async def add_to_blacklist(request):
            """
            添加到IP黑名单（管理员功能）
            
            Headers:
            Authorization: Bearer {session_token}
            
            Request Body:
            {
                "ip": "192.168.1.100"
            }
            
            Response:
            {
                "success": true,
                "message": "已添加到黑名单"
            }
            """
            # 应用认证中间件
            return await self._auth_middleware(request, self._add_to_blacklist_handler)
        
        async def _add_to_blacklist_handler(self, request):
            """添加到黑名单处理函数"""
            user_data = request["user"]
            
            # 检查是否为管理员
            if not user_data.get("is_admin"):
                return web.json_response({
                    "success": False,
                    "message": "需要管理员权限"
                }, status=403)
            
            try:
                data = await request.json()
            except json.JSONDecodeError:
                return web.json_response({
                    "success": False,
                    "message": "无效的JSON数据"
                }, status=400)
            
            ip = data.get("ip")
            if not ip:
                return web.json_response({
                    "success": False,
                    "message": "缺少IP地址"
                }, status=400)
            
            security_manager.add_to_blacklist(ip)
            
            return web.json_response({
                "success": True,
                "message": f"已添加到黑名单: {ip}"
            })
        
