        @routes.get("/api/admin/security/rate-limit-status")
        async def get_rate_limit_status(request):
            """
            获取速率限制状态（管理员功能）
            
            Headers:
            Authorization: Bearer {session_token}
            
            Query Parameters:
            ip: 客户端IP地址（可选）
            user_id: 用户ID（可选）
            
            Response:
            {
                "success": true,
                "data": {
                    "login": {
                        "remaining": 8,
                        "reset_in": 30,
                        "limit": 10,
                        "window": 60
                    },
                    "register": {
                        "remaining": 3,
                        "reset_in": 1200,
                        "limit": 5,
                        "window": 3600
                    },
                    "api": {
                        "remaining": 85,
                        "reset_in": 15,
                        "limit": 100,
                        "window": 60
                    },
                    "ip_allowed": true,
                    "ip_blocked": false
                }
            }
            """
            # 应用认证中间件
            return await self._auth_middleware(request, self._get_rate_limit_status_handler)
        
        async def _get_rate_limit_status_handler(self, request):
            """获取速率限制状态处理函数"""
            user_data = request["user"]
            
            # 检查是否为管理员
            if not user_data.get("is_admin"):
                return web.json_response({
                    "success": False,
                    "message": "需要管理员权限"
                }, status=403)
            
            # 获取查询参数
            query = request.rel_url.query
            ip = query.get("ip", self._get_client_ip(request))
            user_id = query.get("user_id")
            
            # 获取速率限制状态
            status = security_manager.get_rate_limit_status(ip, user_id)
            
            return web.json_response({
                "success": True,
                "data": status
            })
